//! # icons — this renderer's canonical `ICON_NAME` → glyph mapping
//!
//! The canonical vocabulary is the **protocol** (`pathland_core::icon`,
//! spec/ICONS.md) — the spec never lists a renderer's glyphs. This module is
//! the **web renderer's own** mapping: a canonical name → a **filled** Remix
//! Icon `<path>` (vendored from Remix Icon v4.9.1, Apache-2.0 — see
//! `THIRD_PARTY_NOTICES.md`). It is the single source both the SSR renderer and
//! (via `pathland-ts-codegen` → `generated/icons.ts`) the DOM client consume, so
//! the two cannot drift.

/// The filled `<svg>` opening tag (the catalog entries supply only the inner
/// markup). `fill="currentColor"` tints the glyph via `COLOR`/`foregroundStyle`.
pub const WEB_SVG_OPEN: &str = concat!(
    "<svg class=\"pathland-icon\" xmlns=\"http://www.w3.org/2000/svg\" ",
    "viewBox=\"0 0 24 24\" fill=\"currentColor\">"
);

/// The closing `</svg>` tag.
pub const WEB_SVG_CLOSE: &str = "</svg>";

/// The fallback inner markup for an unknown/extension icon name.
pub fn web_fallback_svg() -> &'static str {
    "<circle cx=\"12\" cy=\"12\" r=\"8\"/>"
}

/// The canonical inner SVG markup (a single filled Remix `<path>`) for a
/// canonical name (`None` for unknown names — fall back to
/// [`web_fallback_svg`]). Callers wrap it in [`WEB_SVG_OPEN`]…[`WEB_SVG_CLOSE`].
