#[cfg(test)]
mod tests {
    use std::collections::HashSet;

    #[test]
    fn every_canonical_name_maps_to_a_filled_glyph() {
        let mut seen = HashSet::new();
        for name in pathland_core::icon::NAMES {
            let inner = super::web_inner(name);
            assert!(inner.is_some(), "{} has no web glyph", name);
            let inner = inner.unwrap();
            assert!(inner.starts_with("<path"), "{} is a filled path", name);
            assert!(!inner.contains("stroke="), "{} has no stroke", name);
            assert!(seen.insert(name), "duplicate name {}", name);
        }
        assert_eq!(super::web_inner("definitely-not-an-icon"), None);
        assert!(super::web_fallback_svg().contains("circle"));
    }
}
